rows=[]
for c,s,e,p,st,d,pe,u,a,n,b,cf in S:
    notes=[n] if n else []
    notes.append(RES[c].replace("@"," @")+"fps" if "@" in RES[c] else RES[c])
    if c in GROK: notes.append("'Grok' watermark text bottom-right (x~88-97%, y~95-98%) - crop ~5% or blur")
    if c in GEM: notes.append("Gemini sparkle watermark bottom-right (x~82-87%, y~88-92%)")
    rows.append(dict(clip=c,start=round(s,2),end=round(e,2),duration=round(e-s,2),product=p,shot_type=st,
        description=d,people=pe,usable=u,avoid_reason=a,notes="; ".join(notes),borderline=b,crop_fix=cf))
json.dump(rows,open(OUT,"w"),indent=1,ensure_ascii=False)
# sanity
ALLOWED={"product_hero","product_closeup","texture","application","blend_absorb","glow_face","before_after","skin_science_anim","ingredient_anim","spf_shield","dull_skin_before","spots_before","other"}
assert all(r["shot_type"] in ALLOWED for r in rows)
assert all(r["end"]>r["start"] for r in rows)
assert all((r["usable"] and not r["avoid_reason"]) or (not r["usable"] and r["avoid_reason"]) for r in rows)
assert all(len(r["description"].split())<=20 for r in rows), [r["description"] for r in rows if len(r["description"].split())>20]
print(len(rows),"segments;",sum(r["usable"] for r in rows),"usable;",len({r["clip"] for r in rows}),"clips")
